const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mahajangaPoint = ee.Geometry.Point(46.32, -15.22); // Approximate center of Mahajanga
  const cityBuffer = mahajangaPoint.buffer(5000); // 5km buffer to represent the city area
  const startDate = '2020-01-01';
  const endDate = '2020-01-31';
  const scale = 5566; // CHIRPS Daily resolution is ~5.5 km, use this scale for reducer

  // 2. Data Acquisition & Check
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  const jan2020Rain = chirps
    .filterDate(startDate, endDate)
    .filterBounds(cityBuffer);

  const imageCount = await jan2020Rain.size().getInfo();

  if (imageCount === 0) {
    console.log("No CHIRPS daily rainfall data found for January 2020 in Mahajanga.");
    console.log("C1");
    return;
  }
  console.log(`Jan 2020 Images: ${imageCount}`);

  // 3. Processing
  // Sum the daily precipitation for the month
  const totalRainfallImage = jan2020Rain.sum();

  // Calculate the mean precipitation over the city buffer
  const meanRainfall = await totalRainfallImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: cityBuffer,
    scale: scale,
    maxPixels: 1e9
  }).get('precipitation').getInfo(); // 'precipitation' is the band name for CHIRPS

  // 4. Calculation
  if (meanRainfall === null || isNaN(meanRainfall)) {
    console.log("Calculation of mean rainfall returned null or NaN.");
    console.log("C3");
    return;
  }

  // Convert mm to inches (1 inch = 25.4 mm)
  const totalRainfallInches = meanRainfall / 25.4;
  const thresholdInches = 12;

  // 5. Validation & Final Answer
  console.log(`Total rainfall (mm): ${meanRainfall.toFixed(2)}`);
  console.log(`Total rainfall (inches): ${totalRainfallInches.toFixed(2)}`);
  console.log(`Threshold: ${thresholdInches} inches`);

  if (totalRainfallInches > thresholdInches) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
